        { id = "bru_nucleo_guardia_vil", level = 2, name = "Nucleo demoniaco: Guardia Vil", type = "informativo", description = "Un corazon que nunca parece dejar de gotear sangre. Mientras lo lleves: ventaja en chequeos de Fuerza (Atletismo) y Sabiduria (Supervivencia), y puedes lanzar armadura de mago a voluntad.\nNivel 5: conoces arma magica y puedes lanzarlo sin gastar una ranura una vez por descanso largo.\nNivel 9: conoces furia de sangre y heroismo y puedes lanzarlo sin gastar una ranura una vez por descanso largo.", core = { source = "guardia vil", advantage = "Fuerza (Atletismo) y Sabiduria (Supervivencia)", atWill = "Armadura de mago", tiers = { { level = 5, spell = "Arma magica" }, { level = 9, spell = "furia de sangre y heroismo" } } }, requiredCore = "guardia_vil", spellGrants = { { level = 2, ids = { "armadura_de_mago" } }, { level = 5, ids = { "arma_magica" } } }, effects = {} },
