        { id = "bru_nucleo_diablillo", level = 2, name = "Nucleo demoniaco: Diablillo", type = "informativo", description = "Un fragmento roto de cuerno, caliente al tacto. Mientras lo lleves: ventaja en chequeos de Destreza (Juego de Manos) y Destreza (Sigilo), y puedes lanzar el truco Burla danina.\nNivel 5: conoces parpadeo y puedes lanzarlo sin gastar una ranura una vez por descanso largo.\nNivel 9: conoces lluvia de fuego y puedes lanzarlo sin gastar una ranura una vez por descanso largo.", core = { source = "diablillo", advantage = "Destreza (Juego de Manos) y Destreza (Sigilo)", atWill = "Burla danina", tiers = { { level = 5, spell = "Parpadeo" }, { level = 9, spell = "lluvia de fuego" } } }, requiredCore = "diablillo", spellGrants = { { level = 2, ids = { "burla_danina" } }, { level = 5, ids = { "parpadeo" } } }, effects = {} },
        { id = "bru_nucleo_sucubo", level = 2, name = "Nucleo demoniaco: Sucubo", type = "informativo", description = "Parece un tubo de lapiz labial. Mientras lo lleves: ventaja en chequeos de Carisma (Engano) y Carisma (Persuasion), y puedes lanzar persona encantada a voluntad.\nNivel 5: conoces Sugestion y puedes lanzarlo sin gastar una ranura una vez por descanso largo.\nNivel 9: conoces dominar persona y puedes lanzarlo sin gastar una ranura una vez por descanso largo.", core = { source = "sucubo", advantage = "Carisma (Engano) y Carisma (Persuasion)", atWill = "persona encantada", tiers = { { level = 5, spell = "Sugestion" }, { level = 9, spell = "dominar persona" } } }, requiredCore = "sucubo", spellGrants = { { level = 2, ids = { "hechizar_persona" } }, { level = 5, ids = { "sugestion" } } }, effects = {} },
