        { id = "bru_circulo_demoniaco", level = 3, name = "Circulo demoniaco", cast = "accion_adicional", type = "accion", description = "Gastas 1 fragmento de alma como acción adicional para crear un círculo de runas de 5 pies durante 1 minuto. Mientras permanezcas en el, tienes ventaja en chequeos de concentración.", resourceKey = "soul_shard", resourceCost = 1, selfCondition = { id = "circulo_demoniaco", duration = "manual" }, effects = {} },
        { id = "bru_quemar_alma_extender", level = 3, name = "Quemar alma: Extender", type = "accion", description = "Al lanzar un conjuro con duración de 1 hora o mas, gastas 1 fragmento de alma para extender su duración un numero de horas igual a tu nivel de brujo.", resourceKey = "soul_shard", resourceCost = 1, spendResourceOnAnnounce = true, effects = {} },
        { id = "bru_quemar_alma_acelerar", level = 3, name = "Quemar alma: Acelerar", type = "accion", description = "Al lanzar un conjuro con tiempo de lanzamiento de 10 minutos o menos, gastas 1 fragmento de alma para lanzarlo como una acción.", resourceKey = "soul_shard", resourceCost = 1, spendResourceOnAnnounce = true, effects = {} },
        { id = "bru_quemar_alma_rebotar", level = 3, name = "Quemar alma: Rebotar", type = "reaccion", description = "Cuando un conjuro de objetivo único falla o su objetivo supera la salvación, gastas 1 fragmento de alma para redirigirlo a otro objetivo dentro de su alcance.", resourceKey = "soul_shard", resourceCost = 1, spendResourceOnAnnounce = true, effects = {} },
        { id = "bru_ritos_alma", level = 3, name = "Ritos de alma", type = "accion", description = "Gastas 1 fragmento de alma para lanzar como ritual un conjuro de brujo con etiqueta de ritual, siempre que dispongas del nivel de lanzamiento necesario. La seleccion del conjuro se confirma en el Compendio.", resourceKey = "soul_shard", resourceCost = 1, spendResourceOnAnnounce = true, effects = {} },
        ASI("brujo", 4),
