        { id = "bru_forja_fuego", level = 5, name = "Piedra de Fuego", cast = "accion", type = "accion", resourceKey = "soul_shard", resourceCost = 1, carriedCharge = { condition = "piedra_fuego" }, description = "Accion: gastas un fragmento de alma para forjarla. Al lanzar un conjuro de brujo puedes gastar la piedra para que inflija un golpe critico con una tirada de 19 o 20. Si el conjuro no usa tirada de ataque, inflige dano como si fuera de un nivel de conjuro superior.", effects = {} },
        { id = "bru_forja_salud", level = 5, name = "Piedra de Salud", cast = "accion", type = "accion", resourceKey = "soul_shard", resourceCost = 1, carriedCharge = { condition = "piedra_salud", grant = { resource = "health", ability = "Inteligencia", perClassLevel = "brujo", perLevelDiv = 1, noun = "curacion" } }, description = "Accion: gastas un fragmento de alma para forjarla. Tu u otra criatura podeis aplastarla como accion para recuperar puntos de golpe iguales a tu modificador de Inteligencia mas tu nivel de brujo.", effects = {} },
        { id = "bru_forja_alma", level = 5, name = "Piedra de Alma", cast = "accion", type = "accion", resourceKey = "soul_shard", resourceCost = 1, carriedCharge = { condition = "piedra_alma" }, description = "Accion: gastas un fragmento de alma para forjarla. Puedes gastarla para lanzar reanimar sin gastar ranura ni proporcionar componentes materiales. Si te reducen a 0 puntos de golpe llevando una, se gasta automaticamente y en su lugar te quedas con 1 punto de golpe.", effects = {} },
        { id = "bru_forja_conjuro", level = 5, name = "Piedra de Conjuro", cast = "accion", type = "accion", resourceKey = "soul_shard", resourceCost = 1, carriedCharge = { condition = "piedra_conjuro" }, description = "Accion: gastas un fragmento de alma para forjarla. Puedes gastarla al lanzar un conjuro de brujo para que una criatura tenga desventaja en su primera tirada de salvacion contra ese conjuro.", effects = {} },
        { id = "bru_nigromancia_del_vacio_nivel_6", level = 11, name = "Nigromancia del Vacío (Nivel 6)", type = "informativo", description = "*Característica de brujo de nivel 11* Puedes forzarte a lanzar conjuros más poderosos un cierto número de veces por día. Obtienes una ranura de conjuro de nivel 6. Esta ranura puede gastarse para lanzar cualquier conjuro de brujo que conozcas. Recuperas cualquier ranura de conjuros de Nigromancia del Vacío gastada al finalizar un descanso prolongado. Cada vez que obtengas una ranura de conjuro mediante Nigromancia del Vacío, también aprendes un solo conjuro de brujo de un nivel que puedas lanzar. Estos se cuentan por separado de tus conjuros normales, como se muestra en la columna de Conjuros Conocidos de la tabla del Brujo. A niveles superiores. Obtienes más ranuras de conjuro: una ranura de conjuro de nivel 7 a nivel 13, una de nivel 8 a nivel 15 y una de nivel 9 a nivel 17.", effects = {} },
        { id = "bru_nigromancia_del_vacio_nivel_7", level = 13, name = "Nigromancia del Vacío (Nivel 7)", type = "informativo", description = "Puedes forzarte a lanzar conjuros más poderosos un cierto número de veces por día. Obtienes una ranura de conjuro de nivel 6. Esta ranura puede gastarse para lanzar cualquier conjuro de brujo que conozcas. Recuperas cualquier ranura de conjuros de Nigromancia del Vacío gastada al finalizar un descanso prolongado. Cada vez que obtengas una ranura de conjuro mediante Nigromancia del Vacío, también aprendes un solo conjuro de brujo de un nivel que puedas lanzar. Estos se cuentan por separado de tus conjuros normales, como se muestra en la columna de Conjuros Conocidos de la tabla del Brujo. A niveles superiores. Obtienes más ranuras de conjuro: una ranura de conjuro de nivel 7 a nivel 13, una de nivel 8 a nivel 15 y una de nivel 9 a nivel 17.", effects = {} },
    },
