-- Rasgos generados a partir de las Maldiciones elegidas (Brujo, Estudio de la Afliccion). Mismo
-- patron que las maniobras del Guerrero: la opcion elegida se convierte en un rasgo real para que
-- el Libro pueda mostrarla y ejecutarla. `usesFrom` hace que gasten la reserva de Corrupcion en vez
-- de tener usos propios, que es lo que dice el manual.
do
    local clase = API.GetClass and API.GetClass("brujo")
    local sub
    for _, sc in ipairs((clase and clase.subclasses) or {}) do
        if sc.id == "afliccion" then sub = sc break end
    end
    local eleccion
    for _, f in ipairs((sub and sub.features) or {}) do
        if f.id == "bru_afl_maldiciones" then eleccion = f break end
    end
    for _, opcion in ipairs((eleccion and eleccion.choice and eleccion.choice.options) or {}) do
        sub.features[#sub.features + 1] = {
            id = "bru_afl_mald_" .. tostring(opcion.id),
            level = 2,
            name = opcion.label,
            type = "accion",
            description = opcion.desc,
            requiresOption = opcion.id,
            usesFrom = "bru_afl_corrupcion",
            -- Accion adicional o reaccion segun la Maldicion; sin esto todas gastaban la accion.
            cast = opcion.cast,
            actionKind = "malediction",
            -- La CD de las Maldiciones es la de tus conjuros de brujo (Carisma).
            dcAbility = "Carisma",
            -- Lo que le pasa a la victima. Se resuelve DESPUES de gastar la Corrupcion, porque el
            -- gasto ocurre igual aunque la salvacion la supere.
            area = opcion.area,
            effects = {},
        }
    end
end
